import customers from './mock/customers.json' with { type: 'json' };
import projects from './mock/projects.json' with { type: 'json' };
import opportunities from './mock/opportunities.json' with { type: 'json' };
import persons from './mock/persons.json' with { type: 'json' };
import actions from './mock/actions.json' with { type: 'json' };
import agents from './mock/agents.json' with { type: 'json' };
import { AIInsightCard } from '../components/AIInsightCard.js';
import { ActionCard } from '../components/ActionCard.js';
import { ScoreCard } from '../components/ScoreCard.js';
import { Timeline } from '../components/Timeline.js';
import { RelationGraph } from '../components/RelationGraph.js';

const money = value => `¥${(Number(value) / 10000).toFixed(0)}万`;
const byId = (items, id) => items.find(item => item.id === id);
const activePath = () => window.location.pathname === '/' ? '/' : (window.location.pathname.startsWith('/customer/') ? '/customer' : (window.location.pathname.startsWith('/profile/') ? '/profile' : (window.location.pathname.startsWith('/opportunity/') ? '/opportunity' : (window.location.pathname.startsWith('/project/') ? '/project' : (window.location.pathname.startsWith('/customer-development/') ? '/customer-development' : window.location.pathname)))));
const salesNavItems = [['/','⌂','首页'],['/customer','◎','客户360'],['/customer-development','◉','客户开发'],['/opportunity','◈','商机360'],['/project','▣','项目360'],['/project-management','▣','项目管理'],['/profile','◉','客户画像'],['/agent','✦','Agent助手'],['/actions','✓','行动中心']];
const managementNavItems = [['/legacy?view=ontology','◇','业务本体'],['/legacy-semantic?view=semantic','◌','语义规则'],['/legacy?view=relationships','⇄','关系配置'],['/legacy?view=agents','✦','Agent配置'],['/legacy?view=facts','✓','事实审核'],['/legacy?view=scoring','◈','评分模型'],['/legacy?view=forecast','▣','预测模型'],['/legacy?view=governance','⚙','数据治理']];
let drawerState = { type: 'customer', context: {} };
let insights = [];
let realAgentDataLoaded = false;
let realAgentDataLoading = false;
const uid = prefix => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const currentContext = () => { const path = window.location.pathname; const parts = path.split('/').filter(Boolean); return { customerId: parts[0] === 'customer' || parts[0] === 'profile' ? parts[1] || customers[0]?.id : parts[0] === 'project' ? byId(projects, parts[1] || projects[0]?.id)?.customerId : parts[0] === 'opportunity' ? byId(opportunities, parts[1] || opportunities[0]?.id)?.customerId : null, projectId: parts[0] === 'project' ? parts[1] || projects[0]?.id : parts[0] === 'opportunity' ? byId(opportunities, parts[1] || opportunities[0]?.id)?.projectId : null, opportunityId: parts[0] === 'opportunity' ? parts[1] || opportunities[0]?.id : null }; };
const field = (label, name, value = '', type = 'text', required = false) => `<label class="entry-field"><span>${label}${required ? ' *' : ''}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required ? 'required' : ''} /></label>`;
const selectField = (label, name, options, value = '', required = false) => `<label class="entry-field"><span>${label}${required ? ' *' : ''}</span><select name="${name}" ${required ? 'required' : ''}>${options.map(([key,text]) => `<option value="${esc(key)}" ${String(key) === String(value) ? 'selected' : ''}>${esc(text)}</option>`).join('')}</select></label>`;
function missingInfo(type, context) { const missing = []; if (type === 'opportunity') { const opp = byId(opportunities, context.opportunityId); if (!context.customerId && !opp?.customerId) missing.push('客户'); if (!context.projectId && !opp?.projectId) missing.push('项目'); if (!opp?.sectionId) missing.push('项目标段'); if (!opp?.competitor) missing.push('竞品'); if (!opp?.decisionMaker) missing.push('决策链'); } if (type === 'project' && !context.customerId) missing.push('所属客户'); if (type === 'section' && !context.projectId) missing.push('所属项目'); if (type === 'person' && !context.customerId) missing.push('所属客户'); if (type === 'action' && !context.customerId && !context.projectId && !context.opportunityId) missing.push('关联对象'); return missing; }
function entryDrawer(type = 'customer', context = {}) { const customer = byId(customers, context.customerId) || customers[0]; const project = byId(projects, context.projectId) || projects[0]; const opp = byId(opportunities, context.opportunityId) || opportunities[0]; const miss = missingInfo(type, context); const customerOptions = customers.map(item => [item.id, item.name]); const projectOptions = projects.map(item => [item.id, item.name]); const oppOptions = opportunities.map(item => [item.id, item.name]); const sections = projects.flatMap(item => (item.sections || []).map(section => [section.id, `${item.name} · ${section.name}`])); let title = '新增记录'; let fields = ''; if (type === 'customer') { title = '创建客户'; fields = field('客户名称','name','','text',true) + field('所属行业','industry') + field('区域','region'); } if (type === 'project') { title = '创建 / 编辑项目'; fields = selectField('所属客户','customerId',customerOptions,context.customerId,true) + field('项目名称','name',project?.name || '', 'text',true) + selectField('项目阶段','projectStageCode',[['EARLY_CONTACT','机会识别'],['DISCOVERY','需求确认'],['SOLUTION_REVIEW','方案评审'],['TENDER_PREP','招标准备'],['DELIVERY','交付']],project?.projectStageCode) + field('项目预算','estimatedValue',project?.estimatedValue || '', 'number') + field('预计采购时间','estimatedPurchaseDate','','date'); } if (type === 'section') { title = '补充项目标段'; fields = selectField('所属项目','projectId',projectOptions,context.projectId,true) + field('标段名称','name','','text',true) + field('产品 / 方案','productSolution') + field('标段金额','estimatedAmount','','number') + field('设计院 / 技术方','designOrg'); } if (type === 'opportunity') { title = '创建 / 推进商机'; fields = selectField('客户','customerId',customerOptions,context.customerId || opp?.customerId,true) + selectField('项目','projectId',projectOptions,context.projectId || opp?.projectId,true) + selectField('项目标段','sectionId',sections,opp?.sectionId,true) + field('商机名称','name',opp?.name || '', 'text',true) + selectField('商机阶段','stageCode',[['DISCOVERY','需求确认'],['SOLUTION_QUOTE','方案与报价'],['TENDER_PREP','招标准备'],['WON','成交']],opp?.stageCode) + field('预算金额','amount',opp?.amount || '', 'number') + field('预计采购时间','purchaseDate','','date') + field('竞品','competitor',opp?.competitor || '') + field('决策链 / 预算审批人','decisionMaker',opp?.decisionMaker || ''); } if (type === 'person') { title = '补充关键联系人'; fields = selectField('所属客户','customerId',customerOptions,context.customerId,true) + field('姓名','name','','text',true) + field('职位','title') + selectField('角色','roleType',[['ECONOMIC_BUYER','经济买家'],['PROCUREMENT','采购把关人'],['TECHNICAL','技术负责人'],['BUSINESS_INITIATOR','业务发起人'],['PROJECT_OWNER','项目负责人']], 'BUSINESS_INITIATOR') + selectField('关系状态','relationshipStatus',[['PENDING','待建立'],['IN_PROGRESS','跟进中'],['ESTABLISHED','已建立']], 'PENDING'); } if (type === 'stage') { title = '更新客户开发阶段'; fields = selectField('客户','customerId',customerOptions,context.customerId,true) + selectField('AT 阶段','developmentStage',[['AT1','AT1 客户识别'],['AT2','AT2 客户立项'],['AT3','AT3 需求引导'],['AT4','AT4 方案共创'],['AT5','AT5 项目成交'],['AT6','AT6 复盘增长']],customer?.developmentStage || 'AT1',true); } if (type === 'action') { title = '创建 Action'; fields = selectField('客户','customerId',[['','不指定'],...customerOptions],context.customerId) + selectField('项目','projectId',[['','不指定'],...projectOptions],context.projectId) + selectField('商机','opportunityId',[['','不指定'],...oppOptions],context.opportunityId) + field('行动标题','title','','text',true) + selectField('优先级','priority',[['高','高'],['中','中'],['低','低']], '中') + field('截止日期','dueDate','','date'); } return `<div class="entry-drawer-backdrop" data-entry-close><aside class="entry-drawer"><div class="entry-drawer-head"><div><span class="tag purple">AI 场景录入</span><h2>${title}</h2><p>只填写当前阶段影响推进的关键信息。</p></div><button class="drawer-close" data-entry-close>×</button></div>${miss.length ? `<div class="entry-missing"><strong>AI 发现缺失信息</strong><span>${miss.join('、')}。补齐后会刷新评分并生成下一步 Action。</span></div>` : ''}<form id="entryForm" data-entry-type="${type}"><div class="entry-grid">${fields}</div><div class="entry-form-foot"><span>提交后保留旧版 API 字段兼容</span><button type="button" class="secondary" data-entry-close>取消</button><button type="submit" class="primary">保存并生成下一步</button></div></form></aside></div>`; }
function openEntryDrawer(type = 'customer', context = {}) { drawerState = { type, context: { ...currentContext(), ...context } }; document.body.insertAdjacentHTML('beforeend', entryDrawer(type, drawerState.context)); bindEntryDrawerEvents(); document.querySelector('[data-entry-close]')?.focus(); }
function closeEntryDrawer() { document.querySelector('.entry-drawer-backdrop')?.remove(); }
async function syncLegacyApi(type, values) { const requests = { opportunity: ['/api/opportunities', {name: values.name, customer: byId(customers, values.customerId)?.name || values.customerId, stage: values.stageCode, amount: Number(values.amount || 0), businessType: 'CRM通用', owner: '李盛云', tags: ['新版场景录入']}], person: ['/api/people', {name: values.name, title: values.title, customerId: values.customerId, role: values.roleType}], action: ['/api/actions', {title: values.title, actionType: 'follow_up', customerId: values.customerId || null, projectId: values.projectId || null, opportunityId: values.opportunityId || null, dueAt: values.dueDate || null, priority: values.priority || 'medium', assignee: '李盛云'}] }; const request = requests[type]; if (!request) return; try { await fetch(request[0], {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(request[1])}); } catch (error) { /* Mock-first mode remains usable when the legacy API is unavailable. */ } }
async function submitEntry(form) { const type = form.dataset.entryType; const values = Object.fromEntries(new FormData(form).entries()); let message = '已保存'; if (type === 'customer') { const item = {id:uid('cus'), shortName:values.name.slice(0,6), level:'POTENTIAL', profileScore:50, profileCompleteness:20, developmentStage:'AT1', developmentStageLabel:'客户识别', annualPotential:0, keyPersonIds:[], projectIds:[], ...values}; customers.push(item); message = '客户已创建'; } if (type === 'project') { const item = byId(projects, values.projectId && drawerState.context.projectId); if (item && drawerState.context.projectId) Object.assign(item, {name:values.name, customerId:values.customerId, projectStageCode:values.projectStageCode, estimatedValue:Number(values.estimatedValue || 0), estimatedPurchaseDate:values.estimatedPurchaseDate}); else { projects.push({id:uid('prj'), customerId:values.customerId, name:values.name, projectStage:'需求确认', projectStageCode:values.projectStageCode, location:'待补充', owner:'李盛云', sectionIds:[], sections:[], progress:0, estimatedValue:Number(values.estimatedValue || 0), nextMilestone:'补充项目信息', estimatedPurchaseDate:values.estimatedPurchaseDate, aiInsight:'新建项目，等待 AI 补齐经营上下文。'}); } message = '项目已保存'; } if (type === 'section') { const target = byId(projects, values.projectId); if (target) { const section = {id:uid('sec'), projectId:target.id, name:values.name, stage:'需求确认', sectionStageCode:'DISCOVERY', productSolution:values.productSolution, estimatedAmount:Number(values.estimatedAmount || 0), designOrg:values.designOrg, opportunityId:null}; target.sections = target.sections || []; target.sections.push(section); target.sectionIds = [...(target.sectionIds || []), section.id]; } message = '项目标段已补充'; } if (type === 'opportunity') { const item = byId(opportunities, drawerState.context.opportunityId); if (item) Object.assign(item, {customerId:values.customerId, projectId:values.projectId, sectionId:values.sectionId, name:values.name, stageCode:values.stageCode, amount:Number(values.amount || 0), competitor:values.competitor, purchaseDate:values.purchaseDate, decisionMaker:values.decisionMaker}); else opportunities.push({id:uid('opp'), customerId:values.customerId, projectId:values.projectId, sectionId:values.sectionId, name:values.name, stage:'需求确认', stageCode:values.stageCode, amount:Number(values.amount || 0), winProbability:30, owner:'李盛云', productSolution:'待补充', competitor:values.competitor, blockers:[], aiRecommendation:'已创建商机，等待 AI 诊断。', updatedAt:new Date().toISOString().slice(0,10)}); message = item ? '商机已更新，阶段条件已重新检查' : '商机已创建'; } if (type === 'person') { const item = {id:uid('per'), customerId:values.customerId, name:values.name, title:values.title, role:values.roleType, roleType:values.roleType, influence:'未知', influenceScore:0, relationship:values.relationshipStatus, relationshipStatus:values.relationshipStatus, relationshipStrength:0, projectIds:[]}; persons.push(item); const customer = byId(customers, values.customerId); if (customer) customer.keyPersonIds = [...(customer.keyPersonIds || []), item.id]; message = '关键联系人已补充'; } if (type === 'stage') { const customer = byId(customers, values.customerId); if (customer) { customer.developmentStage = values.developmentStage; customer.developmentStageLabel = ({AT1:'客户识别',AT2:'客户立项',AT3:'需求引导',AT4:'方案共创',AT5:'项目成交',AT6:'复盘增长'})[values.developmentStage]; customer.profileScore = Math.min(100, Number(customer.profileScore || 0) + 3); } message = '客户开发阶段已更新'; } if (type === 'action') { actions.unshift({id:uid('act'), title:values.title, type:'销售跟进', actionType:'FOLLOW_UP', status:'待执行', priority:values.priority, dueDate:values.dueDate, customerId:values.customerId || null, projectId:values.projectId || null, opportunityId:values.opportunityId || null, assignee:'李盛云', sourceAgentId:'agent-opportunity', reason:'由场景化录入生成的下一步行动', result:null}); message = 'Action 已创建'; } closeEntryDrawer(); render(); toast(message); }

function nativeLayer(title) { const agent = title.includes('客户') ? '客户洞察 Agent' : title.includes('商机') ? '商机推进 Agent' : title.includes('项目') ? '项目预测 Agent' : title.includes('画像') ? 'Customer Insight Agent' : '销售 Copilot'; return `<div class="native-layer"><div class="native-layer-flow"><span>数据</span><i>→</i><span>本体</span><i>→</i><span>语义</span><i>→</i><strong>${agent}</strong><i>→</i><span>执行</span></div><div class="native-layer-context"><small>当前对象</small><b>${title}</b><button class="text-button" data-action="nativeAction">查看可执行行动 →</button></div></div>`; }
function toast(message) { let node = document.querySelector('.app-toast'); if (!node) { document.body.insertAdjacentHTML('beforeend','<div class="app-toast"></div>'); node = document.querySelector('.app-toast'); } node.textContent = message; node.classList.add('show'); clearTimeout(window.__appToastTimer); window.__appToastTimer = setTimeout(() => node.classList.remove('show'), 2200); }
function actionContext(node) { const data = node.closest('[data-customer-id]')?.dataset || {}; const context = { customerId: data.customerId || currentContext().customerId, projectId: data.projectId || currentContext().projectId, opportunityId: data.opportunityId || currentContext().opportunityId }; const opp = byId(opportunities, context.opportunityId); if (opp) { context.customerId ||= opp.customerId; context.projectId ||= opp.projectId; } return context; }
function markActivity(context, result = 'Action 已完成') { const now = new Date().toISOString(); const customer = byId(customers, context.customerId); const project = byId(projects, context.projectId); const opp = byId(opportunities, context.opportunityId); if (customer) { customer.lastActivityAt = now; customer.profileScore = Math.min(100, Number(customer.profileScore || 0) + 2); customer.lastActionResult = result; } if (project) { project.lastActivityAt = now; project.lastActionResult = result; } if (opp) { opp.lastActivityAt = now; opp.lastActionResult = result; opp.winProbability = Math.min(99, Number(opp.winProbability || 0) + 3); if (opp.stageCode === 'DISCOVERY') { opp.stageCode = 'SOLUTION_QUOTE'; opp.stage = '方案与报价'; } } }
function createInsightAction(button) { const card = button.closest('.structured-insight'); const context = actionContext(card); const sourceAgentId = card?.dataset.sourceAgentId || (context.opportunityId ? 'agent-opportunity' : context.projectId ? 'agent-project' : 'agent-customer'); if (!context.customerId && !context.projectId && !context.opportunityId) { toast('无法创建 Action：缺少关联对象'); return; } const item = { id: uid('act'), title: button.dataset.actionTitle || '处理 AI 推荐动作', type:'AI 推荐', actionType:'AI_RECOMMENDATION', status:'待执行', priority:'高', dueDate:new Date(Date.now() + 3 * 86400000).toISOString().slice(0,10), customerId:context.customerId || null, projectId:context.projectId || null, opportunityId:context.opportunityId || null, assignee:'李盛云', sourceAgentId, reason:'来自可追溯 AI 洞察卡片', result:null }; actions.unshift(item); button.textContent = 'Action 已创建'; button.disabled = true; toast(`已创建 Action：${item.title}`); }
function updateActionState(button, status) { const item = actions.find(action => String(action.id) === String(button.dataset.id)); if (!item) return; item.status = status; item.completedAt = status === '已完成' ? new Date().toISOString() : item.completedAt; const context = {customerId:item.customerId, projectId:item.projectId, opportunityId:item.opportunityId}; if (status === '已完成') markActivity(context, `完成：${item.title}`); const card = button.closest('.action-card'); if (card) { const label = card.querySelector('.action-status'); if (label) label.textContent = status; } toast(status === '已完成' ? 'Action 已完成，客户画像和成交概率已回写' : status === '进行中' ? 'Action 已进入进行中' : 'Action 已取消'); }
function shell(title, content) {
  return `<div class="app"><aside class="sidebar"><div class="brand"><span class="brand-mark">AI</span> AI Native CRM</div><div class="nav-label">销售工作台</div>${salesNavItems.map(([path, icon, label]) => `<a class="nav-item ${activePath() === path ? 'active' : ''}" href="${path}"><span class="nav-icon">${icon}</span>${label}</a>`).join('')}<div class="nav-label management-label">管理中心</div>${managementNavItems.map(([path, icon, label]) => `<a class="nav-item management-nav" data-external="true" href="${path}"><span class="nav-icon">${icon}</span>${label}</a>`).join('')}<a class="nav-item return-sales" href="/"><span class="nav-icon">←</span>返回销售工作台</a></aside><main class="main"><header class="topbar"><div class="breadcrumb">AI CRM <strong>${title}</strong></div><label class="copilot"><span>✦</span><input id="copilotInput" placeholder="请输入你的业务问题，例如：帮我分析哪些客户值得重点突破" /><span>⌘K</span></label><a class="secondary management-entry" data-external="true" href="/legacy">管理中心</a><div class="avatar">李</div></header><section class="content">${nativeLayer(title)}${content}</section></main></div>`;
}

function customerPage() {
  const customer = customers[0];
  const customerProjects = projects.filter(item => item.customerId === customer.id);
  const customerOpps = opportunities.filter(item => item.customerId === customer.id);
  const customerPersons = persons.filter(item => customer.keyPersonIds.includes(item.id));
  const customerActions = actions.filter(item => customerOpps.some(opp => opp.id === item.opportunityId));
  return shell('客户360', `<div class="page-head"><div><h1>客户360</h1><p>从客户经营视角，理解机会、关系与下一步动作。</p></div><button class="primary" data-action="copilot">让 Agent 分析客户</button></div><div class="hero-grid"><article class="hero-card"><div class="profile-head"><div><div class="tag blue">${customer.level}</div><h2>${customer.name}</h2><p>${customer.industry} · ${customer.region} · 客户开发 ${customer.developmentStage} ${customer.developmentStageLabel}</p></div><div class="profile-avatar">${customer.shortName.slice(0,1)}</div></div><div class="hero-kpis"><div><strong>${money(customer.annualPotential)}</strong><span>年度潜力</span></div><div><strong>${customerProjects.length}</strong><span>关联项目</span></div><div><strong>${customerPersons.length}</strong><span>关键联系人</span></div><div><strong>${customerOpps.length}</strong><span>在途商机</span></div></div></article>${AIInsightCard({title:'客户洞察 Agent',text:customer.aiSummary,actionLabel:'生成突破策略'})}</div><div class="score-grid">${ScoreCard({label:'客户画像评分',value:customer.profileScore,caption:`完整度 ${customer.profileCompleteness}%`,color:'blue'})}${ScoreCard({label:'增长潜力',value:91,caption:'近三个月项目需求上升',color:'green'})}${ScoreCard({label:'关系覆盖',value:62,caption:'经济买家已建立，采购待加深',color:'purple'})}${ScoreCard({label:'经营风险',value:38,caption:customer.risk,color:'orange'})}</div><div class="two-col"><div><div class="section-title"><h3>关联项目与商机</h3><span>${customerProjects.length} 个项目 · ${customerOpps.length} 个商机</span></div><div class="panel">${customerProjects.map(project => `<div class="list-row"><div><h4>${project.name}</h4><p>${project.projectStage} · ${project.location} · ${money(project.estimatedValue)}</p></div><span class="tag">${project.progress}% 推进</span></div>`).join('')}</div><div class="section-title"><h3>推荐行动</h3><span>由 AI 生成</span></div>${customerActions.map(ActionCard).join('')}</div><div><div class="section-title"><h3>关键关系</h3><span>决策链</span></div><div class="panel">${customerPersons.map(person => `<div class="list-row"><div><h4>${person.name}</h4><p>${person.title} · ${person.role}</p></div><span class="tag ${person.relationship === '已建立' ? 'green' : 'orange'}">${person.relationship}</span></div>`).join('')}</div><div class="section-title"><h3>经营时间线</h3></div><div class="panel">${Timeline([{title:'客户画像已刷新',text:'补充了采购关系和项目证据',time:'今天 09:42',kind:'ai'},{title:'新增项目关联',text:'华东建材智能工厂一期',time:'昨天 16:20'},{title:'完成客户拜访',text:'确认区域营销协同需求',time:'10月10日'}])}</div></div></div>`);
}

function customer360Page(customerId = 'cus-001') {
  const customer = byId(customers, customerId) || customers[0];
  const customerProjects = projects.filter(item => item.customerId === customer.id);
  const customerOpps = opportunities.filter(item => item.customerId === customer.id);
  const customerPersons = persons.filter(item => customer.keyPersonIds.includes(item.id));
  const customerActions = actions.filter(item => customerOpps.some(opp => opp.id === item.opportunityId) || item.projectId && customerProjects.some(project => project.id === item.projectId));
  const relationNodes = [
    {type:'集团', name: customer.name.replace(/(集团|公司)$/, '集团'), meta:'总部 / 集团客户'},
    {type:'客户公司', name: customer.name, meta: `${customer.level} · ${customer.region}`},
    ...customerProjects.slice(0, 2).map(project => ({type:'项目', name: project.name.slice(0, 13), meta: project.projectStage})),
    ...customerPersons.slice(0, 2).map(person => ({type:'关键人', name: person.name, meta: person.role})),
    {type:'设计院', name:'华东建筑设计院', meta:'技术影响方'},
    {type:'总包', name:'华东建设总包集团', meta:'项目执行方'}
  ];
  return shell('客户360', `<div class="page-head"><div><div class="tag blue">客户经营全景 · ${customer.developmentStage}</div><h1>${customer.name}</h1><p>把客户、项目、关系和 AI 行动放在同一个经营上下文里。</p></div><button class="primary" data-action="copilot">让 Agent 分析客户</button></div><section class="panel customer360-identity"><div class="profile-head"><div class="profile-title"><div class="profile-avatar">${customer.shortName.slice(0,1)}</div><div><h2>${customer.name}</h2><p>${customer.industry} · ${customer.region} · 年度潜力 ${money(customer.annualPotential)}</p></div></div><div class="customer360-facts"><span><b>${customer.level}</b><small>客户等级</small></span><span><b>${customer.developmentStage}</b><small>开发阶段</small></span><span><b>${customerProjects.length}</b><small>关联项目</small></span><span><b>${customerPersons.length}</b><small>关键人</small></span></div></div></section><div class="section-title"><h3>AI 客户洞察</h3><span>Customer Intelligence</span></div><div class="customer360-insights">${AIInsightCard({title:'AI 评分 · 86 / 100',text:`客户价值和项目潜力较高，画像完整度 ${customer.profileCompleteness}%。当前已进入 ${customer.developmentStage}，适合从重点项目切入。`,actionLabel:'解释评分'})}${AIInsightCard({title:'机会判断 · 可重点突破',text:'关联项目中有 2 个处于可经营阶段，营销协同和工程材料供应是近期最可能形成收入的切入口。',tone:'green',actionLabel:'查看机会'})}${AIInsightCard({title:'风险提示 · 决策链未闭合',text:customer.risk + '。如果不补齐采购和技术角色，方案评审可能停留在业务交流层。',tone:'orange',actionLabel:'补齐关系'})}${AIInsightCard({title:'推荐策略 · 先关系后方案',text:customer.aiRecommendedAction,actionLabel:'生成策略'})}</div><div class="section-title"><h3>客户关系图谱</h3><span>Ontology Relationship Context</span></div><section class="panel customer360-relation">${RelationGraph(relationNodes)}</section><div class="section-title"><h3>客户开发行动</h3><span>AI 生成 · 可追踪</span></div><div class="customer360-actions">${customerActions.map(ActionCard).join('')}</div><div class="customer360-cta"><button class="primary" data-action="strategy">生成客户开发策略</button><button class="secondary" data-action="visit">生成拜访方案</button><button class="secondary" data-action="competition">分析竞争关系</button></div>`);
}

function opportunityPage() {
  const opp = opportunities[0]; const customer = byId(customers, opp.customerId); const project = byId(projects, opp.projectId); const person = persons.find(p => p.id === customer.keyPersonIds[0]);
  return shell('商机360', `<div class="page-head"><div><div class="tag">${opp.stage}</div><h1>${opp.name}</h1><p>${customer.name} · ${project.name} · ${opp.productSolution}</p></div><button class="primary" data-action="copilot">诊断商机</button></div><div class="metric-grid"><article class="stat-card"><span>商机金额</span><strong>${money(opp.amount)}</strong><small>产品方案：${opp.productSolution}</small></article><article class="stat-card"><span>成交概率</span><strong>${opp.winProbability}%</strong><small>较上周 ↑ 8%</small></article><article class="stat-card"><span>当前阶段</span><strong>${opp.stage}</strong><small>阶段准入 4/5 项完成</small></article><article class="stat-card"><span>推进负责人</span><strong>${opp.owner}</strong><small>最近更新 ${opp.updatedAt}</small></article></div><div class="two-col"><div><div class="section-title"><h3>商机诊断</h3><span>Opportunity Intelligence</span></div>${AIInsightCard({title:'商机推进 Agent',text:opp.aiRecommendation,actionLabel:'采纳行动'})}<div class="section-title"><h3>阶段阻塞</h3><span>${opp.blockers.length} 项待处理</span></div><div class="panel">${opp.blockers.map(item => `<div class="list-row"><div><h4>${item}</h4><p>缺少该事实会降低下一阶段推进可信度</p></div><span class="tag orange">待补齐</span></div>`).join('')}</div><div class="section-title"><h3>下一步行动</h3></div>${actions.filter(item => item.opportunityId === opp.id).map(ActionCard).join('')}</div><div><div class="section-title"><h3>商机关系图</h3></div><div class="panel">${RelationGraph([{type:'客户',name:customer.shortName,meta:customer.level},{type:'项目',name:project.name.slice(0,10),meta:project.projectStage},{type:'关键人',name:person.name,meta:person.role},{type:'标段',name:'营销协同标段',meta:'产品方案'}])}</div><div class="section-title"><h3>推进时间线</h3></div><div class="panel">${Timeline([{title:'完成需求确认',text:'客户确认渠道协同场景',time:'10月12日',kind:'ai'},{title:'方案版本更新',text:'补充区域经营价值测算',time:'10月11日'},{title:'首次商机报备',text:'由客户开发 Agent 生成',time:'10月05日'}])}</div></div></div>`);
}

function opportunity360Page(opportunityId = 'opp-001') { const opp = byId(opportunities, opportunityId) || opportunities[0]; const customer = byId(customers, opp.customerId); const project = byId(projects, opp.projectId); const section = project?.sections?.find(item => item.id === opp.sectionId) || {name:'营销协同标段',stage:opp.stage,productSolution:opp.productSolution}; const oppActions = actions.filter(item => item.opportunityId === opp.id); const stageNames = ['商机报备','商机确认','商机跟踪','标前引导','成交']; const stageIndex = opp.stageCode === 'SOLUTION_QUOTE' ? 3 : opp.stageCode === 'TENDER_PREP' ? 2 : opp.stageCode === 'DISCOVERY' ? 1 : 0; return shell('商机360', `<div class="page-head"><div><div class="tag blue">Opportunity · ${opp.stage}</div><h1>${opp.name}</h1><p>${customer.name} → ${project.name} → ${section.name}</p></div><button class="primary" data-action="diagnose">让 Agent 推进诊断</button></div><section class="opportunity360-context"><div class="opportunity360-context-item"><span>客户</span><strong>${customer.name}</strong><small>${customer.level} · ${customer.region}</small></div><div class="opportunity360-arrow">→</div><div class="opportunity360-context-item"><span>项目</span><strong>${project.name}</strong><small>${project.projectStage} · ${project.location}</small></div><div class="opportunity360-arrow">→</div><div class="opportunity360-context-item"><span>项目标段</span><strong>${section.name}</strong><small>${section.productSolution}</small></div></section><div class="metric-grid"><article class="stat-card"><span>商机金额</span><strong>${money(opp.amount)}</strong><small>${opp.productSolution}</small></article><article class="stat-card"><span>成交概率</span><strong>${opp.winProbability}%</strong><small>AI 预测 · 较上周 ↑ 8%</small></article><article class="stat-card"><span>商机类型</span><strong>项目型销售</strong><small>工程材料 / 解决方案</small></article><article class="stat-card"><span>当前负责人</span><strong>${opp.owner}</strong><small>更新于 ${opp.updatedAt}</small></article></div><div class="section-title"><h3>商机阶段流程</h3><span>工程销售推进门槛</span></div><section class="panel opportunity360-stage"><div class="opportunity360-stage-line">${stageNames.map((name,index) => `<div class="opportunity360-stage-step ${index < stageIndex ? 'done' : index === stageIndex ? 'current' : ''}"><span>${index < stageIndex ? '✓' : index + 1}</span><strong>${name}</strong><small>${['识别项目机会','确认客户与需求','建立关系与方案','影响技术规格','合同与交付'][index]}</small></div>`).join('')}</div><div class="opportunity360-gate"><b>当前阶段：${opp.stage}</b><span>已完成 4 / 5 项阶段条件 · 下一门槛：确认预算审批人与技术规格影响人</span></div></section><div class="two-col"><div><div class="section-title"><h3>AI 推进建议</h3><span>Opportunity Intelligence Agent</span></div><div class="opportunity360-ai-grid">${AIInsightCard({title:'当前问题',text:`${opp.blockers[0] || '关键事实仍不完整'}。这会让商机停留在${opp.stage}，无法进入下一阶段。`,actionLabel:'定位问题'})}${AIInsightCard({title:'缺失信息',text:opp.blockers.join(' · ') || '暂无缺失信息',tone:'orange',actionLabel:'创建核验任务'})}${AIInsightCard({title:'推荐动作',text:opp.aiRecommendation,tone:'green',actionLabel:'采纳下一步'})}</div><div class="section-title"><h3>Action 任务</h3><span>下一步行动 · 可追踪</span></div>${oppActions.map(ActionCard).join('')}</div><div><div class="section-title"><h3>竞争分析</h3><span>工程项目竞争态势</span></div><section class="panel opportunity360-competition"><div class="competition-row"><div><span class="tag orange">竞品</span><h4>立邦竞品 A · 低价方案</h4><p>在报价阶段具备价格优势，可能通过总包关系切入。</p></div><strong>中风险</strong></div><div class="competition-row"><div><span class="tag">竞争风险</span><h4>设计规格尚未锁定</h4><p>如果技术规格被竞品预埋，后续价格竞争会放大。</p></div><strong>高风险</strong></div><div class="competition-response"><b>AI 应对策略</b><p>先通过设计院完成产品性能和交付能力验证，再用项目全生命周期价值测算回应低价竞争。</p><button class="text-button" data-action="competition">生成竞争作战卡 →</button></div></section><div class="section-title"><h3>商机事件</h3></div><div class="panel">${Timeline([{title:'方案评审待安排',text:'邀请采购负责人和区域业务负责人',time:'下一步',kind:'ai'},{title:'需求已确认',text:'渠道协同与营销自动化成为核心场景',time:'10月12日'},{title:'项目标段识别',text:`从${project.name}识别出${section.name}`,time:'10月05日'}])}</div></div></div>`); }

function projectPage() { const project = projects[0]; const customer = byId(customers, project.customerId); const sections = [{name:'营销协同标段',status:'方案评审',value:680000},{name:'数据中台标段',status:'需求确认',value:600000}]; return shell('项目360', `<div class="page-head"><div><div class="tag green">${project.projectStage}</div><h1>${project.name}</h1><p>${customer.name} · ${project.location} · 负责人 ${project.owner}</p></div><button class="primary" data-action="copilot">识别项目机会</button></div><div class="hero-grid"><article class="hero-card"><h2>项目推进 ${project.progress}%</h2><p>${project.aiInsight}</p><div class="hero-kpis"><div><strong>${money(project.estimatedValue)}</strong><span>项目规模</span></div><div><strong>${sections.length}</strong><span>项目标段</span></div><div><strong>${project.nextMilestone}</strong><span>下一里程碑</span></div></div></article>${AIInsightCard({title:'项目突破 Agent',text:'建议先影响数据中台标段的技术规格，再把营销协同标段的价值证明带入采购评审。',tone:'green',actionLabel:'生成标段策略'})}</div><div class="two-col"><div><div class="section-title"><h3>项目标段</h3><span>Project Section</span></div><div class="panel">${sections.map(section => `<div class="list-row"><div><h4>${section.name}</h4><p>${section.status} · ${money(section.value)}</p></div><span class="tag">查看商机 →</span></div>`).join('')}</div><div class="section-title"><h3>项目参与方</h3></div><div class="panel">${persons.filter(person => person.projectIds.includes(project.id)).map(person => `<div class="list-row"><div><h4>${person.name}</h4><p>${person.title} · ${person.role}</p></div><span class="tag ${person.relationship === '已建立' ? 'green' : 'orange'}">${person.relationship}</span></div>`).join('')}</div></div><div><div class="section-title"><h3>项目事件</h3></div><div class="panel">${Timeline([{title:'标段识别完成',text:'从项目资料中识别出 2 个可经营标段',time:'今天 10:12',kind:'ai'},{title:'项目阶段更新',text:'从需求确认进入方案评审',time:'昨天 14:36'},{title:'项目建立',text:'客户开发主线自动关联',time:'10月06日'}])}</div></div></div>`); }

function project360Page(projectId = 'prj-001') { const project = byId(projects, projectId) || projects[0]; const customer = byId(customers, project.customerId); const projectOpps = opportunities.filter(item => item.projectId === project.id); const lifecycle = ['机会','设计','招标','施工','交付']; const stageIndex = project.projectStageCode === 'TENDER_PREP' ? 2 : project.projectStageCode === 'DISCOVERY' ? 1 : project.projectStageCode === 'EARLY_CONTACT' ? 0 : 1; const orgs = [{role:'甲方',name:customer.name,meta:'建设单位 · 客户'}, {role:'设计院',name:'华东建筑设计院',meta:'技术规格影响方'}, {role:'总包',name:'华东建设总包集团',meta:'项目执行方'}, {role:'代理商',name:'华东工程材料代理',meta:'渠道与交付伙伴'}]; return shell('项目360', `<div class="page-head"><div><div class="tag green">工程项目经营驾驶舱 · ${project.projectStage}</div><h1>${project.name}</h1><p>${customer.name} · ${project.location} · 项目负责人 ${project.owner}</p></div><button class="primary" data-action="projectPredict">运行项目预测</button></div><section class="project360-hero panel"><div class="project360-hero-top"><div><h2>项目生命周期推进 ${project.progress}%</h2><p>${project.aiInsight}</p></div><div class="project360-value"><strong>${money(project.estimatedValue)}</strong><span>预计项目规模</span></div></div><div class="project360-lifecycle">${lifecycle.map((stage,index) => `<div class="project360-life-step ${index < stageIndex ? 'done' : index === stageIndex ? 'current' : ''}"><span>${index < stageIndex ? '✓' : index + 1}</span><strong>${stage}</strong><small>${['机会识别','方案与设计','招标采购','现场施工','交付验收'][index]}</small></div>`).join('')}</div></section><div class="metric-grid"><article class="stat-card"><span>预计采购时间</span><strong>2026-11</strong><small>基于项目阶段和招标准备进度</small></article><article class="stat-card"><span>项目成交概率</span><strong>68%</strong><small>AI 预测 · 当前趋势 ↑ 5%</small></article><article class="stat-card"><span>关联标段</span><strong>${project.sections?.length || project.sectionIds.length}</strong><small>可经营项目切入口</small></article><article class="stat-card"><span>关联商机</span><strong>${projectOpps.length}</strong><small>金额 ${money(projectOpps.reduce((sum,item) => sum + item.amount, 0))}</small></article></div><div class="section-title"><h3>参与组织</h3><span>项目关系网络</span></div><div class="project360-org-grid">${orgs.map(org => `<article class="organization-card"><span>${org.role}</span><h4>${org.name}</h4><p>${org.meta}</p><button class="text-button" data-action="orgInsight">查看关系判断 →</button></article>`).join('')}</div><div class="two-col"><div><div class="section-title"><h3>项目标段与产品方案</h3><span>Project Section</span></div><div class="panel project360-sections">${(project.sections || []).map(section => { const opp = byId(opportunities, section.opportunityId); return `<div class="project360-section-row"><div><span class="tag">${section.stage}</span><h4>${section.name}</h4><p>${section.productSolution}</p></div><div class="project360-section-side"><strong>${opp ? money(opp.amount) : '待估算'}</strong><small>${opp ? `成交概率 ${opp.winProbability}%` : '尚未形成商机'}</small></div></div>`; }).join('')}</div><div class="section-title"><h3>关联商机</h3><span>从项目进入销售推进</span></div>${projectOpps.map(opp => `<div class="action-card project360-opp-card"><div><h4>${opp.name}</h4><p>${opp.stage} · ${money(opp.amount)} · 成交概率 ${opp.winProbability}%</p></div><span class="tag blue">查看商机 →</span></div>`).join('')}</div><div><div class="section-title"><h3>AI 项目预测</h3><span>Project Intelligence Agent</span></div><div class="project360-ai">${AIInsightCard({title:'采购时间预测',text:'预计客户将在 2026 年 11 月进入集中采购，主要依据是技术规格书确认和招标准备进度。',actionLabel:'查看预测证据'})}${AIInsightCard({title:'风险点',text:'数据中台标段的技术负责人尚未进入关系图，可能影响规格书锁定和后续招标条件。',tone:'orange',actionLabel:'生成风险行动'})}${AIInsightCard({title:'推荐动作',text:'在招标前完成设计院技术交流，同时让甲方业务负责人确认两个标段的预算优先级。',tone:'green',actionLabel:'创建项目计划'})}</div><div class="section-title"><h3>项目事件</h3></div><div class="panel">${Timeline([{title:'预计进入招标准备',text:'项目阶段由设计转向招标',time:'未来 2 周',kind:'ai'},{title:'方案评审会议',text:'确认营销协同标段方案边界',time:'10月16日'},{title:'项目建立',text:'由客户开发主线自动关联',time:'10月06日'}])}</div></div></div>`); }

function agentPage() { return shell('Agent助手', `<div class="page-head"><div><h1>Agent助手</h1><p>让 Agent 理解当前业务上下文，直接生成可执行的下一步行动。</p></div></div><div class="agent-layout"><div><div class="section-title"><h3>可用 Agent</h3></div><div class="agent-list">${agents.map((agent,index) => `<button class="agent-item ${index === 0 ? 'active' : ''}"><strong>✦ ${agent.name}</strong><span>${agent.scene} · ${agent.status}</span></button>`).join('')}</div></div><div><div class="copilot-panel"><h2>今天要解决什么业务问题？</h2><p>你可以直接提问，Agent 会结合客户、项目、标段、商机和行动上下文回答。</p><div class="prompt-box"><input placeholder="例如：哪些客户值得重点突破？为什么？" /><button data-action="ask">发送</button></div></div><div class="section-title"><h3>推荐问题</h3></div><div class="metric-grid"><button class="stat-card" data-action="ask">哪些客户值得重点突破？<small>客户洞察 Agent</small></button><button class="stat-card" data-action="ask">这个商机为什么还不能推进？<small>商机推进 Agent</small></button><button class="stat-card" data-action="ask">项目哪个标段最值得切入？<small>项目突破 Agent</small></button><button class="stat-card" data-action="ask">帮我生成明天的拜访计划<small>销售执行 Agent</small></button></div><div class="section-title"><h3>最近生成的行动</h3></div>${actions.slice(0,3).map(ActionCard).join('')}</div></div>`); }

function agentAssistantPage() { const topCustomers = [{name:'浙江华盛建材集团',score:92,reason:'3 个项目机会 · 历史采购稳定 · 设计院关系已建立',level:'战略突破'},{name:'杭州城投建设集团',score:86,reason:'项目增长明显 · 采购窗口预计在 60 天内打开',level:'重点跟进'},{name:'宁波新材工程有限公司',score:78,reason:'关系基础较弱，但存在 2 个早期项目线索',level:'关系培育'}]; return shell('Agent助手', `<div class="page-head"><div><div class="tag purple">Sales AI Copilot · Workflow</div><h1>销售 AI Copilot</h1><p>不是聊天机器人，而是把业务问题拆成证据、判断和行动的销售工作流。</p></div><span class="tag green">Agent 在线</span></div><div class="assistant-layout"><aside class="assistant-sidebar"><div class="assistant-sidebar-head"><span>工作台 Agent</span><small>选择一个推理能力</small></div>${[['客户洞察 Agent','分析客户价值与突破优先级','✦'],['商机推进 Agent','诊断阶段阻塞与下一步','◈'],['项目预测 Agent','预测采购时间与项目风险','▣'],['方案生成 Agent','生成工程项目解决方案','◇']].map((item,index) => `<button class="assistant-agent ${index === 0 ? 'active' : ''}"><i>${item[2]}</i><span><strong>${item[0]}</strong><small>${item[1]}</small></span><em>${index === 0 ? '运行中' : '可调用'}</em></button>`).join('')}<div class="assistant-context"><span>当前上下文</span><p>客户：浙江区域<br/>时间范围：未来12个月<br/>目标：重点突破客户识别</p></div></aside><section class="assistant-main"><div class="assistant-query"><div class="assistant-query-label"><span>当前任务</span><small>客户洞察 Agent · 结构化分析</small></div><div class="assistant-query-text">帮我分析浙江区域重点客户</div><button class="primary" data-action="agentRun">重新运行</button></div><div class="workflow-strip"><div class="workflow-step done"><span>1</span><strong>理解问题</strong><small>识别区域与目标</small></div><div class="workflow-step done"><span>2</span><strong>读取证据</strong><small>客户、采购、项目、关系</small></div><div class="workflow-step current"><span>3</span><strong>生成判断</strong><small>排序突破优先级</small></div><div class="workflow-step"><span>4</span><strong>转成行动</strong><small>创建任务与计划</small></div></div><div class="section-title"><h3>分析过程</h3><span>可解释推理链 · 已完成 3/3</span></div><div class="analysis-grid"><article class="analysis-card"><span class="analysis-icon">◎</span><div><strong>客户画像</strong><p>识别区域内 18 个活跃客户，按客户价值、增长潜力和画像完整度建立候选集。</p></div><b>18</b></article><article class="analysis-card"><span class="analysis-icon green">↗</span><div><strong>历史采购</strong><p>对比近 24 个月采购趋势，筛出采购稳定且存在增购可能的客户。</p></div><b>24月</b></article><article class="analysis-card"><span class="analysis-icon purple">▣</span><div><strong>项目机会</strong><p>关联项目和标段，预测未来 12 个月内的预算和采购窗口。</p></div><b>9</b></article><article class="analysis-card"><span class="analysis-icon orange">⌘</span><div><strong>关系网络</strong><p>检查甲方、设计院、总包和采购角色的关系覆盖，识别突破阻塞。</p></div><b>4层</b></article></div><div class="section-title"><h3>分析结果</h3><span>按重点突破优先级排序</span></div><div class="assistant-results">${topCustomers.map((item,index) => `<article class="assistant-result"><div class="result-rank">0${index + 1}</div><div class="result-body"><div><h4>${item.name}</h4><span class="tag ${index === 0 ? 'purple' : index === 1 ? 'blue' : 'orange'}">${item.level}</span></div><p>${item.reason}</p></div><div class="result-score"><strong>${item.score}</strong><small>AI 评分</small></div></article>`).join('')}</div><div class="section-title"><h3>建议行动</h3><span>把判断交给销售执行</span></div><div class="assistant-actions"><article class="assistant-action"><div><strong>建立浙江区域重点客户攻坚清单</strong><p>包含 TOP 3 客户、突破理由和建议负责人</p></div><button class="primary" data-action="createTask">创建任务</button></article><article class="assistant-action"><div><strong>生成浙江区域拜访计划</strong><p>按客户优先级和项目采购窗口安排 30 天节奏</p></div><button class="secondary" data-action="createPlan">生成计划</button></article></div></section></div>`); }

function profilePage() { const customer = customers[0]; return shell('客户画像', `<div class="page-head"><div><h1>客户画像</h1><p>可被 Agent 使用的客户认知上下文，所有事实都可追溯。</p></div><button class="secondary" data-action="refresh">刷新画像</button></div><article class="panel"><div class="profile-head"><div class="profile-title"><div class="profile-avatar">${customer.shortName.slice(0,1)}</div><div><h2>${customer.name}</h2><p>${customer.industry} · ${customer.region} · 画像版本 v3</p></div></div><span class="tag green">已确认事实 18 条</span></div><div class="score-grid" style="margin-top:22px">${ScoreCard({label:'客户价值',value:88,caption:'战略级客户',color:'blue'})}${ScoreCard({label:'增长潜力',value:91,caption:'项目需求增长',color:'green'})}${ScoreCard({label:'关系覆盖',value:62,caption:'仍需补齐采购关系',color:'purple'})}${ScoreCard({label:'风险',value:38,caption:'预算节点待确认',color:'orange'})}</div></article><div class="two-col"><div><div class="section-title"><h3>画像事实</h3><span>来源可追溯</span></div><div class="panel"><div class="list-row"><div><h4>集团数字化战略</h4><p>客户已确认区域营销协同和渠道增长需求</p></div><span class="tag green">置信度 92%</span></div><div class="list-row"><div><h4>采购决策链</h4><p>营销副总裁已建立，区域采购负责人跟进中</p></div><span class="tag">置信度 78%</span></div><div class="list-row"><div><h4>潜在项目池</h4><p>关联 2 个项目，预计规模 ${money(customer.annualPotential)}</p></div><span class="tag">系统推断</span></div></div></div><div><div class="section-title"><h3>画像摘要</h3></div>${AIInsightCard({title:'Customer Insight Agent',text:customer.aiSummary,actionLabel:'查看证据链'})}<div class="section-title"><h3>待确认事实</h3></div><div class="panel"><div class="list-row"><div><h4>最终预算审批人</h4><p>影响商机进入签约阶段</p></div><span class="tag orange">待核验</span></div><div class="list-row"><div><h4>数据中台技术负责人</h4><p>影响智能工厂项目规格书</p></div><span class="tag orange">待核验</span></div></div></div></div>`); }

function profile360Page(customerId = 'cus-001') { const customer = byId(customers, customerId) || customers[0]; const customerProjects = projects.filter(item => item.customerId === customer.id); const customerOpps = opportunities.filter(item => item.customerId === customer.id); const customerPersons = persons.filter(item => customer.keyPersonIds.includes(item.id)); const scoreModel = [{label:'客户价值',value:88,weight:'25%',caption:'年度潜力与历史采购规模',color:'blue'},{label:'合作基础',value:82,weight:'20%',caption:'既有项目和交付基础',color:'green'},{label:'关系强度',value:62,weight:'20%',caption:'经济买家已建立，采购关系待加深',color:'purple'},{label:'项目机会',value:91,weight:'20%',caption:`未来12个月识别 ${customerProjects.length + 1} 个项目机会`,color:'green'},{label:'战略匹配',value:79,weight:'15%',caption:'行业方向与方案能力匹配',color:'orange'}]; const profileActions = [{id:'profile-act-1',title:'补齐区域采购负责人关系',type:'关键人策略',status:'待执行',priority:'高',dueDate:'本周',reason:'关系强度是当前画像中最明显的短板。'},{id:'profile-act-2',title:'围绕 2 个重点项目做方案共创',type:'突破路径',status:'进行中',priority:'高',dueDate:'10月18日',reason:'项目机会评分高，适合从项目标段切入。'},{id:'profile-act-3',title:'验证未来12个月项目池',type:'事实核验',status:'待执行',priority:'中',dueDate:'10月21日',reason:'需要用客户访谈确认系统推断的增长机会。'}]; return shell('客户画像', `<div class="page-head"><div><div class="tag purple">AI 动态经营画像 · v3</div><h1>${customer.name}</h1><p>画像不是标签集合，而是 Agent 对客户未来经营空间的当前判断。</p></div><button class="secondary" data-action="refresh">刷新画像</button></div><section class="profile360-hero panel"><div class="profile-head"><div class="profile-title"><div class="profile-avatar">${customer.shortName.slice(0,1)}</div><div><h2>${customer.name}</h2><p>${customer.industry} · ${customer.region} · ${customer.level} · 画像更新时间：今天 09:42</p></div></div><div class="profile360-total"><strong>82</strong><span>/ 100 综合经营分</span><small>↑ 6 分 · 最近30天</small></div></div><div class="profile360-score-grid">${scoreModel.map(item => ScoreCard(item)).join('')}</div></section><div class="section-title"><h3>客户发展阶段</h3><span>AI 判断：当前处于 ${customer.developmentStage} · ${customer.developmentStageLabel}</span></div><section class="panel profile360-at"><div class="profile360-at-line">${['AT1','AT2','AT3','AT4','AT5','AT6'].map((stage,index) => `<div class="profile360-at-step ${index < 2 ? 'done' : index === 2 ? 'current' : ''}"><span>${index < 2 ? '✓' : index + 1}</span><strong>${stage}</strong><small>${['客户识别','客户立项','需求引导','方案共创','项目成交','复盘增长'][index]}</small></div>`).join('')}</div><div class="profile360-stage-note"><b>为什么是 AT3？</b><span>客户需求已经明确，且已有 ${customerOpps.length} 个商机进入业务讨论；下一阶段的关键不是继续收集信息，而是把关键人和项目方案绑定起来。</span></div></section><div class="section-title"><h3>AI 洞察</h3><span>基于事实、关系和项目事件推理</span></div><div class="profile360-insights">${AIInsightCard({title:'机会判断 · 未来12个月存在 3 个项目机会',text:'机会来自三个相互印证的信号：历史采购持续、关联项目数量增长、客户关系基础已经形成。建议把增长机会拆解到具体标段，而不是停留在客户层面。',actionLabel:'查看机会证据'})}${AIInsightCard({title:'原因解释 · 历史采购 + 项目增长',text:'历史采购说明客户已验证合作价值；项目增长说明预算和需求正在扩大；关系基础降低了首次进入项目的成本。',tone:'green',actionLabel:'展开推理链'})}${AIInsightCard({title:'风险提示 · 关系强度低于项目潜力',text:'当前项目机会评分 91，但关系强度只有 62。若不补齐采购与技术角色，机会可能停留在业务发起人层面。',tone:'orange',actionLabel:'生成补关系动作'})}</div><div class="section-title"><h3>客户开发策略</h3><span>由 Customer Insight Agent 输出</span></div><div class="profile360-strategy-grid"><article class="strategy-card"><span class="strategy-icon">↗</span><div><h4>突破路径</h4><p>先以${customerProjects[0]?.name || '重点项目'}的方案评审为入口，绑定营销协同和工程材料两个场景，再向集团级长期合作扩展。</p><button class="text-button" data-action="strategy">生成 30/60/90 天计划 →</button></div></article><article class="strategy-card"><span class="strategy-icon purple">◎</span><div><h4>关键人策略</h4><p>让已建立关系的业务负责人引荐区域采购负责人；同步寻找设计院技术负责人，形成“业务价值 + 技术规格”双线推进。</p><button class="text-button" data-action="visit">生成关键人拜访方案 →</button></div></article><article class="strategy-card"><span class="strategy-icon orange">✦</span><div><h4>下一步动作</h4><p>本周完成方案评审会议，确认预算审批人和技术负责人，并将已确认事实回写客户画像。</p><button class="text-button" data-action="competition">分析竞争关系 →</button></div></article></div><div class="section-title"><h3>AI 推荐行动</h3><span>${profileActions.length} 个待处理</span></div><div class="profile360-actions">${profileActions.map(ActionCard).join('')}</div>`); }

function homePage() { return customerPage(); }
function customerDevelopmentDetailPage(customerId = 'cus-001') { const customer = byId(customers, customerId) || customers[0]; const stageIndex = ['AT1','AT2','AT3','AT4','AT5','AT6'].indexOf(customer.developmentStage); return shell('客户开发', `<div class="page-head"><div><a class="back-link" href="/customer-development">← 返回客户开发列表</a><div class="tag purple">销售工作台 · 客户开发</div><h1>${customer.name} 客户开发</h1><p>销售在 AI CRM 内推进 AT1-AT6、关键人、项目和下一步 Action。</p></div><button class="primary" data-entry-type="stage">更新 AT 阶段</button></div><section class="panel"><div class="section-title"><h3>客户开发阶段</h3><span>销售可操作 · AI 辅助判断</span></div><div class="profile360-at-line">${['AT1','AT2','AT3','AT4','AT5','AT6'].map((stage,index) => `<div class="profile360-at-step ${stage === customer.developmentStage ? 'current' : index < stageIndex ? 'done' : ''}"><span>${index < stageIndex ? '✓' : index + 1}</span><strong>${stage}</strong><small>${['客户识别','客户立项','需求引导','方案共创','项目成交','复盘增长'][index]}</small></div>`).join('')}</div></section><div class="two-col"><section class="panel"><div class="section-title"><h3>客户开发操作</h3></div><button class="primary" data-entry-type="person">补充关键联系人</button><button class="secondary" data-entry-type="project">创建项目</button><button class="secondary" data-entry-type="opportunity">创建商机</button></section><section class="panel"><div class="section-title"><h3>AI 下一步建议</h3></div>${AIInsightCard({title:'客户开发 Agent',judgment:'当前应从关键人和重点项目两个方向推进客户开发。',evidence:'客户阶段、项目池、关系覆盖和商机状态',problem:'采购负责人和技术负责人仍未完全覆盖',missing:'预算审批人和技术规格影响人',recommendation:'补充关键联系人并绑定到重点项目',sourceAgentId:'agent-customer',customerId:customer.id})}</section></div>`); }
function customerDevelopmentPage() { const stageLabels = {AT1:'客户识别',AT2:'客户立项',AT3:'需求引导',AT4:'方案共创',AT5:'项目成交',AT6:'复盘增长'}; const stageCount = stage => customers.filter(item => item.developmentStage === stage).length; const totalPotential = customers.reduce((sum,item) => sum + Number(item.annualPotential || 0), 0); return shell('客户开发', `<div class="page-head"><div><div class="tag purple">销售工作台 · 客户开发</div><h1>客户开发</h1><p>按 AT1-AT6 管理客户推进状态，把客户阶段、项目机会和下一步行动放在同一张清单里。</p></div><button class="primary" data-entry-type="customer">＋ 新建客户开发</button></div><div class="metric-grid development-summary"><article class="stat-card"><span>客户开发总数</span><strong>${customers.length}</strong><small>覆盖全部销售客户</small></article><article class="stat-card"><span>本月重点推进</span><strong>${customers.filter(item => ['AT2','AT3','AT4'].includes(item.developmentStage)).length}</strong><small>处于中段推进期</small></article><article class="stat-card"><span>预计客户潜力</span><strong>${money(totalPotential)}</strong><small>未来 12 个月</small></article><article class="stat-card"><span>待补齐画像</span><strong>${customers.filter(item => Number(item.profileCompleteness || 0) < 70).length}</strong><small>画像完整度低于 70%</small></article></div><div class="section-title"><h3>客户开发列表</h3><span>${customers.length} 个客户 · 按当前阶段排序</span></div><section class="panel development-list"><div class="development-toolbar"><div class="development-search">⌕ <input id="developmentSearch" placeholder="搜索客户名称、行业或区域" /></div><select id="developmentStageFilter"><option value="">全部阶段</option>${Object.entries(stageLabels).map(([key,label]) => `<option value="${key}">${key} ${label}（${stageCount(key)}）</option>`).join('')}</select><button class="secondary" data-action="developmentRefresh">刷新列表</button></div><div class="development-table-wrap"><table class="table development-table"><thead><tr><th>客户</th><th>当前阶段</th><th>画像完整度</th><th>项目 / 商机</th><th>预计潜力</th><th>负责人</th><th></th></tr></thead><tbody>${customers.map(item => { const projectCount = projects.filter(project => project.customerId === item.id).length; const oppCount = opportunities.filter(opp => opp.customerId === item.id).length; const stage = item.developmentStage || 'AT1'; const stageClass = stage === 'AT1' ? 'orange' : stage === 'AT6' ? 'green' : 'purple'; return `<tr data-development-row data-search="${esc(`${item.name} ${item.industry} ${item.region}`)}" data-stage="${stage}"><td><a class="development-customer" href="/customer-development/${item.id}"><span class="profile-avatar">${esc(item.shortName.slice(0,1))}</span><span><strong>${esc(item.name)}</strong><small>${esc(item.industry)} · ${esc(item.region)}</small></span></a></td><td><span class="tag ${stageClass}">${stage} · ${stageLabels[stage]}</span><small class="development-next">${stage === 'AT1' ? '待完成客户立项' : stage === 'AT2' ? '待进入需求引导' : '建议推进关键人和项目'}</small></td><td><div class="development-progress"><i style="width:${Number(item.profileCompleteness || 0)}%"></i></div><small>${Number(item.profileCompleteness || 0)}%</small></td><td><strong>${projectCount}</strong> 个项目 · <strong>${oppCount}</strong> 个商机</td><td><strong>${money(item.annualPotential)}</strong></td><td>李盛云</td><td><a class="text-button" href="/customer-development/${item.id}">查看详情 →</a></td></tr>`; }).join('')}</tbody></table></div><div class="development-empty" hidden>没有匹配的客户开发记录，请调整筛选条件。</div></section>`); }
function projectManagementPage() { const stageLabels = {DISCOVERY:'需求确认',SOLUTION_QUOTE:'方案与报价',TENDER_PREP:'招标准备',WON:'成交'}; const totalAmount = opportunities.reduce((sum,item) => sum + Number(item.amount || 0), 0); return shell('项目管理', `<div class="page-head"><div><div class="tag blue">销售工作台 · 项目管理</div><h1>项目管理</h1><p>从项目、标段到商机统一管理经营推进；在这里查看商机、创建商机并进入推进工作区。</p></div><div class="page-head-actions"><button class="secondary" data-entry-type="project">＋ 新建项目</button><button class="primary" data-entry-type="opportunity">＋ 新建商机</button></div></div><div class="metric-grid management-summary"><article class="stat-card"><span>项目总数</span><strong>${projects.length}</strong><small>按客户和阶段管理</small></article><article class="stat-card"><span>在途商机</span><strong>${opportunities.length}</strong><small>可继续推进的商机</small></article><article class="stat-card"><span>商机总金额</span><strong>${money(totalAmount)}</strong><small>当前商机池</small></article><article class="stat-card"><span>待推进商机</span><strong>${opportunities.filter(item => item.stageCode !== 'WON').length}</strong><small>需要下一步 Action</small></article></div><div class="management-workspace"><section><div class="section-title"><h3>项目列表</h3><span>${projects.length} 个项目</span></div><div class="panel management-project-list">${projects.map(project => { const customer = byId(customers, project.customerId); const projectOpps = opportunities.filter(item => item.projectId === project.id); return `<a class="management-project-row" href="/project/${project.id}"><div><span class="tag green">${esc(project.projectStage)}</span><h4>${esc(project.name)}</h4><p>${esc(customer?.name || '未关联客户')} · ${esc(project.location)} · ${projectOpps.length} 个商机</p></div><div class="management-project-side"><strong>${money(project.estimatedValue)}</strong><small>${project.progress}% 推进</small><span>查看项目 →</span></div></a>`; }).join('')}</div></section><section><div class="section-title"><h3>商机列表</h3><span>商机创建与推进入口</span></div><div class="panel management-opportunity-panel"><div class="management-toolbar"><div class="development-search">⌕ <input id="managementOpportunitySearch" placeholder="搜索商机、客户或项目" /></div><select id="managementOpportunityStage"><option value="">全部阶段</option>${Object.entries(stageLabels).map(([key,label]) => `<option value="${key}">${label}</option>`).join('')}</select></div><div class="management-opportunity-list">${opportunities.map(opp => { const customer = byId(customers, opp.customerId); const project = byId(projects, opp.projectId); const stage = stageLabels[opp.stageCode] || opp.stage; return `<article class="management-opportunity-row" data-management-opportunity data-search="${esc(`${opp.name} ${customer?.name || ''} ${project?.name || ''}`)}" data-stage="${esc(opp.stageCode || '')}"><div class="management-opp-main"><div class="management-opp-title"><a href="/opportunity/${opp.id}"><strong>${esc(opp.name)}</strong></a><span class="tag ${opp.stageCode === 'TENDER_PREP' ? 'orange' : opp.stageCode === 'WON' ? 'green' : 'purple'}">${esc(stage)}</span></div><p>${esc(customer?.name || '未关联客户')} · ${esc(project?.name || '未关联项目')} · ${esc(opp.productSolution || '方案待补充')}</p><small>负责人：${esc(opp.owner || '李盛云')} · 更新于 ${esc(opp.updatedAt || '待更新')}</small></div><div class="management-opp-metrics"><strong>${money(opp.amount)}</strong><span>成交概率 ${opp.winProbability}%</span><a class="text-button" href="/opportunity/${opp.id}">推进商机 →</a></div></article>`; }).join('')}</div><div class="development-empty management-empty" hidden>没有匹配的商机，请调整搜索或阶段筛选。</div></div></section></div>`); }
function actionCenterPage() { return shell('行动中心', `<div class="page-head"><div><div class="tag purple">Sales Workspace</div><h1>行动中心</h1><p>集中处理由 AI 洞察、客户经营、商机推进和项目预测生成的行动。</p></div><button class="primary" data-entry-type="action">创建 Action</button></div><div class="section-title"><h3>待处理行动</h3><span>按优先级和截止时间排序</span></div><div class="customer360-actions">${actions.map(ActionCard).join('')}</div>`); }
const routes = {'/':homePage,'/customer':customerPage,'/customer-development':customerDevelopmentPage,'/opportunity':opportunityPage,'/project':projectPage,'/project-management':projectManagementPage,'/agent':agentAssistantPage,'/profile':profilePage,'/actions':actionCenterPage};
function ensureEntryTrigger() { if (!document.querySelector('.entry-trigger')) { document.body.insertAdjacentHTML('beforeend','<div class="entry-launcher"><button class="entry-trigger floating-entry" data-entry-type="opportunity">＋ 创建商机</button><div class="entry-launcher-menu"><button data-entry-type="customer">客户</button><button data-entry-type="project">项目</button><button data-entry-type="section">标段</button><button data-entry-type="opportunity">商机</button><button data-entry-type="person">关键联系人</button><button data-entry-type="stage">AT 阶段</button><button data-entry-type="action">Action</button></div></div>'); } }
function decorateAgentInsights() { if (!window.location.pathname.startsWith('/agent') || document.querySelector('.agent-structured-insight')) return; const target = document.querySelector('.assistant-results'); const insight = insights[0]; if (target) target.insertAdjacentHTML('beforebegin', `<div class="section-title agent-structured-insight"><h3>AI 洞察闭环</h3><span>来源：${esc(insight?.source || '客户洞察 Agent')}</span></div>${AIInsightCard({title:insight?.name || '客户洞察 Agent',judgment:insight?.judgment || insight?.description || '暂无结构化判断',evidence:Array.isArray(insight?.evidence) ? insight.evidence.join('、') : insight?.evidence || '暂无证据',problem:insight?.risk || '暂无风险',recommendation:insight?.recommendation || '暂无推荐行动',sourceAgentId:insight?.source_agent_id || 'agent-customer',customerId:insight?.customer_id || customers[0]?.id})}`); }
async function loadRealAgentData() { if (realAgentDataLoaded || realAgentDataLoading) return; realAgentDataLoading = true; try { const [insightResponse, actionResponse] = await Promise.all([fetch('/api/insights'), fetch('/api/actions')]); if (insightResponse.ok) insights = await insightResponse.json(); if (actionResponse.ok) { const rows = await actionResponse.json(); actions.splice(0, actions.length, ...rows.map(item => ({...item, type:item.action_type || item.actionType || '销售行动', status:({pending:'待执行',in_progress:'进行中',accepted:'已采纳',dismissed:'已取消',expired:'已过期',completed:'已完成',cancelled:'已取消'})[item.status] || item.status, priority:item.priority === 'high' ? '高' : item.priority === 'low' ? '低' : item.priority || '中', dueDate:item.due_at || item.dueDate, reason:item.reason || item.description || '来自结构化洞察'}))); } realAgentDataLoaded = true; if (window.location.pathname.startsWith('/agent') || window.location.pathname.startsWith('/actions')) render(); } catch (error) { /* API 不可用时保留本地演示数据 */ } finally { realAgentDataLoading = false; } }
document.addEventListener('submit', event => { const form = event.target.closest?.('#entryForm'); if (form) syncLegacyApi(form.dataset.entryType, Object.fromEntries(new FormData(form).entries())); });
function bindEntryDrawerEvents() { document.querySelectorAll('[data-entry-close]').forEach(node => { node.onclick = event => { if (event.target === node || event.target.closest('.drawer-close')) closeEntryDrawer(); }; }); const form = document.querySelector('#entryForm'); if (form) form.onsubmit = event => { event.preventDefault(); submitEntry(form); }; }
function bindEntryEvents() { document.querySelectorAll('.entry-trigger,.entry-launcher-menu button,[data-entry-type]').forEach(button => { button.onclick = () => openEntryDrawer(button.dataset.entryType || 'customer'); }); bindEntryDrawerEvents(); document.querySelectorAll('[data-action="createInsightAction"]').forEach(button => button.addEventListener('click', () => createInsightAction(button))); document.querySelectorAll('[data-action="start"]').forEach(button => button.addEventListener('click', () => updateActionState(button, '进行中'))); document.querySelectorAll('[data-action="complete"]').forEach(button => button.addEventListener('click', () => updateActionState(button, '已完成'))); document.querySelectorAll('[data-action="cancel"]').forEach(button => button.addEventListener('click', () => updateActionState(button, '已取消'))); document.querySelectorAll('[data-action="delay"]').forEach(button => button.addEventListener('click', () => { const item = actions.find(action => String(action.id) === String(button.dataset.id)); if (item) { const next = new Date(item.dueDate || Date.now()); next.setDate(next.getDate() + 3); item.dueDate = next.toISOString().slice(0,10); item.status = '进行中'; } toast('Action 已延期 3 天并进入进行中'); })); }
async function loadGovernanceContext() { const context = currentContext(); const customerFactsUrl = context.customerId ? `/api/customers/${context.customerId}/facts` : '/api/facts/pending'; const urls = {assets:'/api/semantic-assets', relationships:'/api/relationships', facts:customerFactsUrl, agents:'/api/agents', scores:'/api/relationship-score-models', gates:'/api/stage-definitions'}; const entries = await Promise.all(Object.entries(urls).map(async ([key,url]) => { try { const response = await fetch(url); return [key, response.ok ? await response.json() : null]; } catch (error) { return [key, null]; } })); return Object.fromEntries(entries); }
function governanceItems(payload) { const pick = value => Array.isArray(value) ? value : value?.items || value?.data || value?.results || []; return {assets:pick(payload.assets), relationships:pick(payload.relationships), facts:pick(payload.facts), agents:pick(payload.agents), scores:pick(payload.scores), gates:pick(payload.gates)}; }
function renderGovernancePanels(payload) { const data = governanceItems(payload); const path = window.location.pathname; const root = document.querySelector('#app'); if (!root || root.querySelector('.governance-context-panel')) return; const agentNames = data.agents.slice(0,3).map(item => item.name || item.id).filter(Boolean).join('、') || 'Agent 配置未返回'; const evidence = data.facts.slice(0,3).map(item => item.factName || item.name || item.label || item.id).filter(Boolean).join('、') || '事实接口暂无可展示记录'; const relationships = data.relationships.slice(0,3).map(item => item.relationshipType || item.type || `${item.sourceType || '对象'} → ${item.targetType || '对象'}`).filter(Boolean).join('、') || '关系接口暂无可展示记录'; const score = data.scores[0]?.name || data.scores[0]?.modelName || '评分模型'; const gates = data.gates.slice(0,3).map(item => item.name || item.stageName || item.code).filter(Boolean).join('、') || '阶段准入规则'; const asset = data.assets.slice(0,2).map(item => item.name || item.assetName || item.code).filter(Boolean).join('、') || '语义资产'; let title = '治理依据'; let body = ''; if (path.startsWith('/customer') || path.startsWith('/profile')) { title = '评分依据 · 只读'; body = `<div><b>${score}</b><span>评分模型</span></div><div><b>${evidence}</b><span>关联事实</span></div><div><b>${relationships}</b><span>关系证据</span></div><div><b>${asset}</b><span>语义资产</span></div>`; } else if (path.startsWith('/opportunity')) { title = '阶段缺失条件 · 只读'; body = `<div><b>${gates}</b><span>阶段准入规则</span></div><div><b>${evidence}</b><span>待核验事实</span></div><div><b>${relationships}</b><span>关系覆盖</span></div>`; } else if (path.startsWith('/project')) { title = '预测依据 · 只读'; body = `<div><b>${asset}</b><span>预测语义资产</span></div><div><b>${evidence}</b><span>项目事实</span></div><div><b>${agentNames}</b><span>生成 Agent</span></div>`; } else if (path.startsWith('/agent')) { title = '分析引用链 · 只读'; body = `<div><b>${agentNames}</b><span>引用 Agent</span></div><div><b>${relationships}</b><span>引用关系</span></div><div><b>${evidence}</b><span>引用事实</span></div><div><b>${asset}</b><span>引用语义规则</span></div>`; } else return; root.insertAdjacentHTML('beforeend', `<section class="panel governance-context-panel"><div class="section-title"><h3>${title}</h3><span>来自旧版治理 API · 销售只读</span></div><div class="governance-context-grid">${body}</div></section>`); }
function render() { const path = window.location.pathname; const content = path.startsWith('/customer/') ? customer360Page(path.split('/')[2]) : path.startsWith('/profile/') ? profile360Page(path.split('/')[2]) : path.startsWith('/opportunity/') ? opportunity360Page(path.split('/')[2]) : path.startsWith('/project/') ? project360Page(path.split('/')[2]) : path.startsWith('/customer-development/') ? customerDevelopmentDetailPage(path.split('/')[2]) : (routes[activePath()] || customerPage)(); document.querySelector('#app').innerHTML = content; decorateAgentInsights(); ensureEntryTrigger(); bindEvents(); bindEntryEvents(); bindDevelopmentFilters(); bindManagementFilters(); loadGovernanceContext().then(renderGovernancePanels); if (path.startsWith('/agent') || path.startsWith('/actions')) loadRealAgentData(); }
function bindEvents() { document.querySelectorAll('[data-action="copilot"], [data-action="diagnose"]').forEach(button => button.addEventListener('click', () => { document.querySelector('#copilotInput')?.focus(); })); document.querySelector('[data-action="nativeAction"]')?.addEventListener('click', event => { event.target.textContent = '已定位到推荐行动'; document.querySelector('.assistant-actions, .customer360-cta, .profile360-actions, .opportunity360-ai, .project360-ai')?.scrollIntoView({behavior:'smooth',block:'center'}); }); document.querySelectorAll('[data-action="ask"]').forEach(button => button.addEventListener('click', () => { alert('Agent 已接收问题，将结合客户、项目与商机上下文回答并生成行动。'); })); document.querySelectorAll('[data-action="complete"]').forEach(button => button.addEventListener('click', () => { button.textContent = '已加入行动中心'; button.disabled = true; })); document.querySelector('[data-action="refresh"]')?.addEventListener('click', event => { event.target.textContent = '刷新任务已创建'; }); document.querySelector('#copilotInput')?.addEventListener('keydown', event => { if (event.key === 'Enter' && event.target.value.trim()) alert(`Agent 正在分析：${event.target.value}`); }); ['strategy','visit','competition','projectPredict','orgInsight','agentRun','createTask','createPlan'].forEach(type => document.querySelector(`[data-action="${type}"]`)?.addEventListener('click', event => { const labels = {strategy:'策略生成中...',visit:'拜访方案生成中...',competition:'竞争关系分析中...',projectPredict:'项目预测运行中...',orgInsight:'关系判断生成中...',agentRun:'Agent 重新分析中...',createTask:'任务创建中...',createPlan:'计划生成中...'}; const done = {strategy:'策略已生成',visit:'拜访方案已生成',competition:'竞争分析已完成',projectPredict:'预测已更新',orgInsight:'关系判断已生成',agentRun:'分析已完成',createTask:'任务已创建',createPlan:'计划已生成'}; event.target.textContent = labels[type]; setTimeout(() => { event.target.textContent = done[type]; }, 450); })); }
function bindDevelopmentFilters() { const search = document.querySelector('#developmentSearch'); const stage = document.querySelector('#developmentStageFilter'); const rows = [...document.querySelectorAll('[data-development-row]')]; const empty = document.querySelector('.development-empty'); if (!search || !stage) return; const apply = () => { const query = search.value.trim().toLowerCase(); const stageValue = stage.value; let visible = 0; rows.forEach(row => { const matches = (!query || row.dataset.search.toLowerCase().includes(query)) && (!stageValue || row.dataset.stage === stageValue); row.hidden = !matches; if (matches) visible += 1; }); if (empty) empty.hidden = visible !== 0; }; search.addEventListener('input', apply); stage.addEventListener('change', apply); document.querySelector('[data-action="developmentRefresh"]')?.addEventListener('click', event => { event.target.textContent = '已刷新'; setTimeout(() => { event.target.textContent = '刷新列表'; }, 900); }); }
function bindManagementFilters() { const search = document.querySelector('#managementOpportunitySearch'); const stage = document.querySelector('#managementOpportunityStage'); const rows = [...document.querySelectorAll('[data-management-opportunity]')]; const empty = document.querySelector('.management-empty'); if (!search || !stage) return; const apply = () => { const query = search.value.trim().toLowerCase(); const stageValue = stage.value; let visible = 0; rows.forEach(row => { const matches = (!query || row.dataset.search.toLowerCase().includes(query)) && (!stageValue || row.dataset.stage === stageValue); row.hidden = !matches; if (matches) visible += 1; }); if (empty) empty.hidden = visible !== 0; }; search.addEventListener('input', apply); stage.addEventListener('change', apply); }
window.addEventListener('popstate', render); document.addEventListener('click', event => { if (event.target.closest('[data-entry-close]')) { closeEntryDrawer(); return; } const link = event.target.closest('a[href^="/"]'); if (!link) return; if (link.dataset.external === 'true') return; event.preventDefault(); history.pushState({}, '', link.getAttribute('href')); render(); }); render();
